import sys

def rotate90(grid):
    return [''.join(grid[3 - j][i] for j in range(4)) for i in range(4)]

def count_hash(grid):
    return sum(row.count('#') for row in grid)

def get_placements(grid):
    placements = set()
    current = grid
    for _ in range(4):
        positions = [(r, c) for r in range(4) for c in range(4) if current[r][c] == '#']
        if not positions:
            current = rotate90(current)
            continue
        minr = min(r for r, c in positions)
        maxr = max(r for r, c in positions)
        minc = min(c for r, c in positions)
        maxc = max(c for r, c in positions)
        for dr in range(-minr, 3 - maxr + 1):
            for dc in range(-minc, 3 - maxc + 1):
                mask = 0
                for r, c in positions:
                    nr = r + dr
                    nc = c + dc
                    bitpos = nr * 4 + nc
                    mask |= (1 << bitpos)
                placements.add(mask)
        current = rotate90(current)
    return placements

def solve():
    data = sys.stdin.read().splitlines()
    if len(data) != 12:
        print('No')
        return
    grids = [data[i:i+4] for i in range(0, 12, 4)]
    sizes = [count_hash(g) for g in grids]
    if sum(sizes) != 16:
        print('No')
        return
    full = (1 << 16) - 1
    ps = [get_placements(g) for g in grids]
    found = False
    for m1 in ps[0]:
        for m2 in ps[1]:
            if (m1 & m2) == 0:
                covered = m1 | m2
                needed = full ^ covered
                if needed in ps[2]:
                    found = True
                    break
        if found:
            break
    print('Yes' if found else 'No')

solve()
