import sys
from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    idx = 0
    line = data[idx].split()
    N = int(line[0])
    M = int(line[1])
    idx += 1
    grid = data[idx:idx + N]

    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]

    visited = [[False] * M for _ in range(N)]
    touched = [[False] * M for _ in range(N)]

    def slide(r, c, d):
        cr = r
        cc = c
        while True:
            nr = cr + dr[d]
            nc = cc + dc[d]
            if nr < 0 or nr >= N or nc < 0 or nc >= M or grid[nr][nc] == '#':
                return cr, cc
            cr = nr
            cc = nc

    start_r, start_c = 1, 1
    queue = deque([(start_r, start_c)])
    visited[start_r][start_c] = True

    while queue:
        r, c = queue.popleft()
        for d in range(4):
            er, ec = slide(r, c, d)
            if not visited[er][ec]:
                visited[er][ec] = True
                queue.append((er, ec))

    # Mark reachable stops as touched
    for i in range(N):
        for j in range(M):
            if visited[i][j]:
                touched[i][j] = True

    # Mark all cells on slides between reachable stops
    for i in range(N):
        for j in range(M):
            if visited[i][j]:
                for d in range(4):
                    er, ec = slide(i, j, d)
                    if visited[er][ec]:
                        cr, cc = i, j
                        while True:
                            touched[cr][cc] = True
                            if cr == er and cc == ec:
                                break
                            cr += dr[d]
                            cc += dc[d]

    # Count touched ice squares
    count = 0
    for i in range(N):
        for j in range(M):
            if grid[i][j] == '.' and touched[i][j]:
                count += 1
    print(count)

solve()
```

