from typing import Dict, List

def longest_special_substring_length(s: str) -> int:
    n = len(s)
    runs: Dict[str, List[int]] = {}
    i = 0
    while i < n:
        j = i
        c = s[i]
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        if c not in runs:
            runs[c] = []
        runs[c].append(run_len)
        i = j

    for L in range(n, 0, -1):
        for c in runs:
            count = sum(max(0, r - L + 1) for r in runs[c])
            if count >= 3:
                return L
    return -1
