def ways(k: int) -> int:
    def comb(n: int, kk: int) -> int:
        if kk < 0 or kk > n:
            return 0
        k = min(kk, n - kk)
        res = 1
        for i in range(k):
            res = res * (n - i) // (i + 1)
        return res

