    divisors.sort()

    def get_freq(sub: str) -> tuple:
        freq = [0] * 26
        for c in sub:
            freq[ord(c) - ord('a')] += 1
        return tuple(freq)

    for m in divisors:
        first_freq = get_freq(s[:m])
        num_chunks = n // m
        is_good = True
        for i in range(1, num_chunks):
            chunk_freq = get_freq(s[i * m:(i + 1) * m])
            if chunk_freq != first_freq:
                is_good = False
                break
        if is_good:
            return m
    return n
