def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = list(map(int, data[1:1 + N]))

    MAX = 200010
    spf = list(range(MAX + 1))
    for i in range(2, int(MAX ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAX + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_kernel(x, spf):
        res = 1
        while x > 1:
            p = spf[x]
            exp = 0
            while x % p == 0:
                x //= p
                exp += 1
            if exp % 2 == 1:
                res *= p
        return res

    Z = 0
    kernels = []
    for a in A:
        if a == 0:
            Z += 1
        else:
            kernels.append(get_kernel(a, spf))

    nonz = N - Z
    zero_pairs = Z * (Z - 1) // 2 + Z * nonz

    nonzero_pairs = 0
    cnt = Counter(kernels)
    for c in cnt.values():
        nonzero_pairs += c * (c - 1) // 2

    ans = zero_pairs + nonzero_pairs
    print(ans)

