def solution(s: str, k: int) -> str:
    n = len(s)
    if k == 0 or n == 0:
        return ""
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + (1 if s[i] == '1' else 0)

    min_len = n + 1
    for i in range(n):
        for j in range(i + 1, n + 1):
            if prefix[j] - prefix[i] == k:
                min_len = min(min_len, j - i)

    if min_len > n:
        return ""

    best = None
    for i in range(n - min_len + 1):
        j = i + min_len
        if prefix[j] - prefix[i] == k:
            sub = s[i:j]
            if best is None or sub < best:
                best = sub
    return best
