import sys

def solve_tiling():
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx]); idx += 1
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    tiles = []
    areas = []
    for i in range(N):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        tiles.append((a, b))
        areas.append(a * b)
    S = H * W
    # Subset sum check
    if S == 0:
        print("Yes")
        return
    dp = [False] * (S + 1)
    dp[0] = True
    for ar in areas:
        for j in range(S, ar - 1, -1):
            if dp[j - ar]:
                dp[j] = True
    if not dp[S]:
        print("No")
        return
    # Precompute placements
    placements = [[] for _ in range(N)]
    def get_mask(r0, c0, hh, ww, W):
        mask = 0
        for i in range(hh):
            row_start = (r0 + i) * W
            for j in range(ww):
                mask |= (1 << (row_start + c0 + j))
        return mask
    for i in range(N):
        a, b = tiles[i]
        # First orientation: a x b
        ha, wa = a, b
        for r0 in range(H - ha + 1):
            for c0 in range(W - wa + 1):
                placements[i].append(get_mask(r0, c0, ha, wa, W))
        # Second orientation if different
        if a != b:
            ha, wa = b, a
            for r0 in range(H - ha + 1):
                for c0 in range(W - wa + 1):
                    placements[i].append(get_mask(r0, c0, ha, wa, W))
    # Sort tiles by decreasing area
    order = sorted(range(N), key=lambda x: -areas[x])
    areas = [areas[order[j]] for j in range(N)]
    placements = [placements[order[j]] for j in range(N)]
    # Cumulative remaining areas
    cumsum_rem = [0] * (N + 1)
    for k in range(N - 1, -1, -1):
        cumsum_rem[k] = cumsum_rem[k + 1] + areas[k]
    # DFS
    def dfs(k, mask, covered):
        if k == N:
            return covered == S
        if covered + cumsum_rem[k] < S:
            return False
        # Try placing first (large tiles first, prefer placing)
        tile_placements = placements[k]
        for pmask in tile_placements:
            if (mask & pmask) == 0:
                new_covered = covered + areas[k]
                if dfs(k + 1, mask | pmask, new_covered):
                    return True
        # Then skip
        if dfs(k + 1, mask, covered):
            return True
        return False
    if dfs(0, 0, 0):
        print("Yes")
    else:
        print("No")

solve_tiling()
```

