def shortestSubarray(nums: list[int], target: int) -> int:
    n = len(nums)
    pref = [0] * (n + 1)
    for i in range(1, n + 1):
        pref[i] = pref[i - 1] + nums[i - 1]
    S = pref[n]
    value_to_pos = {pref[i]: i for i in range(n)}
    min_len = float('inf')
    target_mod = target % S
    for rl in range(n):
        required = (pref[rl] + target_mod) % S
        if required in value_to_pos:
            rr = value_to_pos[required]
            delta = pref[rr] - pref[rl]
            needed = target - delta
            if needed >= 0 and needed % S == 0:
                k = needed // S
                length = k * n + rr - rl
                if length > 0:
                    min_len = min(min_len, length)
    return int(min_len) if min_len < float('inf') else -1
