    st = [[0] * n for _ in range(logn)]
    for i in range(n):
        st[0][i] = nums[i]
    for j in range(1, logn):
        for i in range(n - (1 << j) + 1):
            st[j][i] = max(st[j - 1][i], st[j - 1][i + (1 << (j - 1))])

    def query(L, R):
        length = R - L + 1
        k = (length).bit_length() - 1
        return max(st[k][L], st[k][R - (1 << k) + 1])

    # Group positions by value
    pos = defaultdict(list)
    for i in range(n):
        pos[nums[i]].append(i)

    total = 0
    for v, lst in pos.items():
        m = len(lst)
        if m == 0:
            continue
        cur = 1
        for k in range(1, m):
            i_start = lst[k - 1]
            i_end = lst[k]
            if query(i_start, i_end) <= v:
                cur += 1
            else:
                total += cur * (cur + 1) // 2
                cur = 1
        total += cur * (cur + 1) // 2
    return total
