import sys

class SegTree:
    def __init__(self, n):
        self.n = n
        self.tree = [(0, 0) for _ in range(4 * (n + 1))]
        self._build(1, 1, n)

    def _build(self, node, start, end):
        if start == end:
            self.tree[node] = (0, start)
            return
        mid = (start + end) // 2
        self._build(2 * node, start, mid)
        self._build(2 * node + 1, mid + 1, end)
        self._merge(node, 2 * node, 2 * node + 1)

    def _merge(self, node, left, right):
        lmax, lid = self.tree[left]
        rmax, rid = self.tree[right]
        if lmax > rmax:
            self.tree[node] = (lmax, lid)
        elif rmax > lmax:
            self.tree[node] = (rmax, rid)
        else:
            self.tree[node] = (lmax, min(lid, rid))

    def update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = (val, start)
            return
        mid = (start + end) // 2
        if idx <= mid:
            self.update(2 * node, start, mid, idx, val)
        else:
            self.update(2 * node + 1, mid + 1, end, idx, val)
        self._merge(node, 2 * node, 2 * node + 1)

def main():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    M = int(input_data[1])
    A = [int(x) for x in input_data[2:2 + M]]
    st = SegTree(N)
    counts = [0] * (N + 1)
    outs = []
    for a in A:
        counts[a] += 1
        st.update(1, 1, N, a, counts[a])
        outs.append(str(st.tree[1][1]))
    print('\n'.join(outs))

if __name__ == "__main__":
    main()
